/* ---------- map ---------- */
function mapSVG(city,dark){const R=rng(hash(city+'map'));const C=dark?{land:'#1B1E24',minor:'#252930',major:'#353B46',water:'#0D1014',park:'#1E2923',lab:'#6E6A63'}:{land:'#EFE8DD',minor:'#FBF8F3',major:'#FFFFFF',water:'#C9DBE3',park:'#DCE4CD',lab:'#A0968A'};
 let s=`<svg viewBox="0 0 1000 700" preserveAspectRatio="none" aria-hidden="true"><rect width="1000" height="700" fill="${C.land}"/>`;
 const ang=R()*30-15;s+=`<g transform="rotate(${ang} 500 350)" stroke="${C.minor}" stroke-width="3">`;for(let i=-200;i<1200;i+=38+R()*14)s+=`<line x1="${i}" y1="-300" x2="${i+R()*40-20}" y2="1000"/>`;for(let j=-300;j<1000;j+=36+R()*14)s+=`<line x1="-300" y1="${j}" x2="1300" y2="${j+R()*40-20}"/>`;s+='</g>';
 for(let i=0;i<6;i++){const x=R()*1000,y=R()*700,w=40+R()*110,h=30+R()*80;s+=`<rect x="${x}" y="${y}" width="${w}" height="${h}" rx="${10+R()*20}" fill="${C.park}" transform="rotate(${R()*40-20} ${x} ${y})"/>`}
 s+=`<g stroke="${C.major}" stroke-width="7" fill="none" stroke-linecap="round">`;for(let i=0;i<7;i++){const y1=R()*700,y2=R()*700;s+=`<path d="M-20 ${y1} C ${300+R()*200} ${y1+R()*200-100}, ${500+R()*200} ${y2+R()*200-100}, 1020 ${y2}"/>`}for(let i=0;i<5;i++){const x1=R()*1000,x2=R()*1000;s+=`<path d="M${x1} -20 C ${x1+R()*160-80} 250, ${x2+R()*160-80} 450, ${x2} 720"/>`}s+='</g>';
 const W={syd:`M0 0H1000V60C900 80 860 120 800 110S700 60 640 140 540 150 480 190 380 170 330 200 240 190 180 160 90 150 0 170Z M930 0H1000V700H960C940 620 900 560 920 480S960 360 940 260 950 120 930 0Z`,
  la:`M0 0H150C120 80 170 160 130 240S60 360 110 440 200 560 180 700H0Z`,
  lis:`M0 700V560C120 520 220 560 330 520S520 470 620 500 820 470 1000 520V700Z`}[city];
 s+=`<path d="${W}" fill="${C.water}"/>`;
 Object.entries(CITY[city].areas).forEach(([n,[x,y]])=>s+=`<text x="${x}" y="${y+46}" text-anchor="middle" fill="${C.lab}" font-size="15" font-family="Instrument Sans,sans-serif" letter-spacing="2" style="text-transform:uppercase">${n.toUpperCase()}</text>`);
 return s+'</svg>'}
function mountMap(el,{city,dark,items,onPin,hover}){const st={z:1,x:0,y:0};el.classList.toggle('lt',!dark);
 el.innerHTML=`<div class="lyr">${mapSVG(city,dark)}${items.map((p,i)=>`<button class="pin" data-pid="${p.id}" style="left:${p.x/10}%;top:${p.y/7}%;--d:${i*.05}s" aria-label="${esc(p.t)}, ${esc(pLabel(p))}">${esc(pLabel(p,{compact:1}))}</button>`).join('')}</div><div class="ctl"><button type="button" data-z="1" aria-label="Zoom in">+</button><button type="button" data-z="-1" aria-label="Zoom out">−</button></div><span class="note">Illustrative map · ${CITY[city].n}</span>`;
 const lyr=$('.lyr',el);const apply=()=>{const W=el.clientWidth,H=el.clientHeight;st.x=clamp(st.x,W-W*st.z,0);st.y=clamp(st.y,H-H*st.z,0);lyr.style.transform=`translate(${st.x}px,${st.y}px) scale(${st.z})`;lyr.style.setProperty('--ps',(1/st.z).toFixed(3));$$('.pin',lyr).forEach(p=>p.style.setProperty('--ps',(1/st.z).toFixed(3)))};
 const zoom=(dz,cx=el.clientWidth/2,cy=el.clientHeight/2)=>{const nz=clamp(st.z*(dz>0?1.35:1/1.35),1,4);st.x=cx-(cx-st.x)*nz/st.z;st.y=cy-(cy-st.y)*nz/st.z;st.z=nz;apply()};
 $$('[data-z]',el).forEach(b=>b.onclick=e=>{e.stopPropagation();zoom(+b.dataset.z)});
 el.onwheel=e=>{if(!e.ctrlKey&&!el.matches(':hover'))return;e.preventDefault();const r=el.getBoundingClientRect();zoom(-e.deltaY,e.clientX-r.left,e.clientY-r.top)};
 let drag=null,moved=0;el.onpointerdown=e=>{if(e.target.closest('.ctl,.mcard'))return;drag={x:e.clientX,y:e.clientY,sx:st.x,sy:st.y};moved=0;el.setPointerCapture(e.pointerId)};
 el.onpointermove=e=>{if(!drag)return;const dx=e.clientX-drag.x,dy=e.clientY-drag.y;moved=Math.abs(dx)+Math.abs(dy);st.x=drag.sx+dx;st.y=drag.sy+dy;apply()};
 el.onpointerup=e=>{const d=drag;drag=null;if(d&&moved<5){const pin=document.elementFromPoint(e.clientX,e.clientY)?.closest('.pin');if(pin&&el.contains(pin))onPin&&onPin(lst(pin.dataset.pid),pin);else if(!e.target.closest('.mcard'))$('.mcard',el)?.remove()}};
 if(hover)$$('.pin',el).forEach(p=>{p.onmouseenter=()=>hover(p.dataset.pid,1);p.onmouseleave=()=>hover(p.dataset.pid,0)});
 apply();return {focus(id){const p=lst(id);if(!p)return;st.z=Math.max(st.z,1.6);const W=el.clientWidth,H=el.clientHeight;st.x=W/2-p.x/1000*W*st.z;st.y=H/2-p.y/700*H*st.z;lyr.style.transition='transform .6s cubic-bezier(.2,.8,.2,1)';apply();setTimeout(()=>lyr.style.transition='',650)}}}
function pinCard(el,p,pin){$('.mcard',el)?.remove();const r=el.getBoundingClientRect(),pr=pin.getBoundingClientRect();const c=document.createElement('a');c.className='mcard';c.href='#p-'+p.id;
 c.innerHTML=`<button class="x" type="button" aria-label="Close">${ic('x','width:14px;height:14px')}</button>${ph(p.img[0],p.t)}<div class="b"><b>${esc(p.t)}</b><span>${esc(p.area)} · ${p.bd} bd · ${p.m2} m²</span><div style="font-weight:700;margin-top:4px">${pLabel(p)}</div></div>`;
 let left=pr.left-r.left+pr.width/2-135,top=pr.top-r.top-270;if(top<10)top=pr.bottom-r.top+10;c.style.left=clamp(left,10,r.width-280)+'px';c.style.top=clamp(top,10,r.height-270)+'px';el.appendChild(c);
 $('.x',c).onclick=e=>{e.preventDefault();e.stopPropagation();c.remove()};$$('.pin',el).forEach(x=>x.classList.toggle('on',x===pin))}

