function lightbox(p,i){closeModal();const lb=document.createElement('div');lb.className='lbx';lb.setAttribute('role','dialog');lb.setAttribute('aria-label','Photo gallery');document.body.appendChild(lb);
 const draw=()=>{lb.innerHTML=`<div class="top"><span>${esc(p.t)} · ${i+1} / ${p.img.length}</span><button class="circ" style="background:transparent;color:#fff;border-color:#555" aria-label="Close">${ic('x')}</button></div><div class="stage"><button class="nv p" aria-label="Previous">${ic('left')}</button><img src="photos/${p.img[i]}.jpg" alt="${esc(p.t)} photo ${i+1}"><button class="nv n" aria-label="Next">${ic('arrow')}</button></div><div class="th">${p.img.map((k,j)=>`<button data-j="${j}" aria-current="${i===j}" aria-label="Photo ${j+1}">${ph(k)}</button>`).join('')}</div>`;
  $('.top .circ',lb).onclick=closeModal;$('.nv.p',lb).onclick=()=>go(-1);$('.nv.n',lb).onclick=()=>go(1);$$('[data-j]',lb).forEach(b=>b.onclick=()=>{i=+b.dataset.j;draw()});$('.top .circ',lb).focus()};
 const go=d=>{i=(i+d+p.img.length)%p.img.length;draw()};lb.addEventListener('nav',e=>go(e.detail));let sx=null;lb.addEventListener('pointerdown',e=>sx=e.clientX);lb.addEventListener('pointerup',e=>{if(sx!=null&&Math.abs(e.clientX-sx)>50)go(e.clientX<sx?1:-1);sx=null});draw()}

/* ---------- DEVELOPMENT ---------- */
function units(d){const out=[],res=ls('reserved')||[];for(let f=d.top;f>d.top-d.floors;f--)for(let u=0;u<d.units;u++){const id=d.s==='marlowe'?`R${(d.top-f)*d.units+u+1}`:`${f}${'ABCD'[u]}`;const h=hash(d.s+id)%100;const mine=res.find(r=>r.dev===d.s&&r.u===id);const st=mine?'rs':h<28?'sd':h<42?'rs':'av';const fl=d.top-f;out.push({id,f,u,st,mine:!!mine,bd:d.beds[u],m2:d.m2[u]+(fl%3)*2,price:Math.round(d.from*(d.m2[u]/d.m2[0])*(1+(f-(d.top-d.floors))*.018)/1000)*1000,asp:['North-east','North','North-west','South'][u]})}return out}
function pageDev(d){const c=CITY[d.city],U=units(d),av=U.filter(u=>u.st==='av').length;
 return `<section class="dv-hero">${ph(d.img[0],d.n)}<div class="in"><div class="wrap"><span class="lab p" style="color:#fff">${d.area}, ${c.n} · ${d.tag}</span>${lines(d.n,'h1')}<div class="dv-facts">${[[U.length,'residences'],[av,'available now'],[d.done,'completion'],[price(d.from,c.cur,{compact:1}),'from']].map(f=>`<div><b class="num">${f[0]}</b><span>${f[1]}</span></div>`).join('')}</div></div></div></section>
 <section class="s wrap"><div class="intro"><div><span class="lab p rv">The project</span><p class="big-p rv" style="margin-top:16px;color:var(--ink)">${d.d}</p></div><div class="rv"><div class="amen" style="grid-template-columns:1fr 1fr">${d.am.map(a=>`<div>${ic('check')}${a}</div>`).join('')}</div></div></div></section>
 <section class="s wrap"><div class="dv-gal">${d.img.slice(1,4).map((k,i)=>`<div class="rv cl" style="--dl:${i*.1}s">${ph(k,d.n).replace('class="ph "','class="ph " style="height:100%"')}</div>`).join('')}</div></section>
 <section class="s wrap" id="avail">${sh('Availability','Choose your <em>residence</em>','Live availability. Tap an available residence to see its plan and price, then reserve with a refundable holding deposit.',`<div class="chips" role="group" aria-label="Bedrooms">${[0,...new Set(d.beds)].map(b=>`<button class="chip" type="button" data-ub="${b}" aria-pressed="${S.bedsF===b}">${b?b+' bed':'All'}</button>`).join('')}</div>`)}
 <div class="avail"><div class="stack"><div class="legend" style="margin-bottom:14px"><span><i style="background:var(--ember-soft);border:1px solid #F6C4AE"></i>Available</span><span><i style="background:var(--stone)"></i>Reserved</span><span><i style="background:#EFEAE2"></i>Sold</span><span><i style="background:var(--ink)"></i>Selected</span></div><div class="bld" id="bld"></div></div><div class="ucard" id="ucard"></div></div></section>`}
function drawUnits(d){const U=units(d);const bld=$('#bld');const floors=[...new Set(U.map(u=>u.f))];bld.innerHTML=floors.map(f=>`<div class="fl" style="--u:${d.units}"><span class="lv">${d.s==='marlowe'?'Row '+(d.top-f+1):'L'+f}</span>${U.filter(u=>u.f===f).map(u=>{const dim=S.bedsF&&u.bd!==S.bedsF;return `<button type="button" class="un ${u.st}" data-u="${u.id}" aria-pressed="${S.unitSel===u.id}" ${u.st!=='av'&&!u.mine?'':''} style="${dim?'opacity:.25':''}" aria-label="${u.id}, ${u.bd} bed, ${u.st==='av'?'available':u.st==='rs'?'reserved':'sold'}">${u.id}${u.mine?' ★':''}</button>`}).join('')}</div>`).join('');
 const sel=U.find(u=>u.id===S.unitSel)||U.find(u=>u.st==='av'&&(!S.bedsF||u.bd===S.bedsF));S.unitSel=sel?.id;const cur=CITY[d.city].cur;const uc=$('#ucard');
 uc.innerHTML=sel?`<span class="lab">Residence ${sel.id} · ${d.s==='marlowe'?'Home':'Level '+sel.f}</span><h3>${sel.bd} bedroom${sel.bd>1?'s':''}</h3><div style="font-family:var(--f-d);font-size:36px" class="num">${price(sel.price,cur)}</div><div class="kf" style="grid-template-columns:repeat(3,1fr);margin:6px 0"><div><b class="num">${sel.m2}</b><span>m² interior</span></div><div><b>${sel.asp.split('-').map(x=>x[0]).join('')}</b><span>${sel.asp} aspect</span></div><div style="border:0"><b>${sel.st==='av'?'Open':sel.st==='rs'?'Held':'Sold'}</b><span>status</span></div></div><div class="fp" style="padding:10px">${floorPlan(sel.bd,sel.m2)}</div>
 ${sel.st==='av'?`<button class="btn em lg" id="rsv">Reserve · ${price(sel.price*.05,cur)} deposit</button><button class="btn lt" id="reg">Register interest</button>`:sel.mine?`<span class="tag st" style="justify-self:start">★ Reserved by you</span><button class="btn lt" id="unrsv">Cancel reservation</button>`:`<p class="muted">This residence is ${sel.st==='rs'?'reserved':'sold'}. Choose an orange residence.</p>`}`:`<p class="muted">No residences match this filter.</p>`;
 $$('.un',bld).forEach(b=>b.onclick=()=>{S.unitSel=b.dataset.u;drawUnits(d)});
 $('#rsv')?.addEventListener('click',()=>reserve(d,sel));$('#reg')?.addEventListener('click',()=>{const m=modal(`<h3>Register interest</h3><p class="muted">We’ll send the ${d.n} brochure, price list and floor plans for residence ${sel.id}.</p><form id="rf" novalidate style="display:grid;gap:10px"><input class="input" id="rn" placeholder="Full name" aria-label="Full name"><input class="input" id="re" type="email" placeholder="Email" aria-label="Email"><p class="err-t" id="rerr" hidden>Please enter your name and a valid email.</p><button class="btn ink lg" type="submit">Send me the brochure</button></form>`);$('#rf',m).onsubmit=e=>{e.preventDefault();if($('#rn').value.trim().length<2||!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test($('#re').value.trim())){$('#rerr').hidden=false;return}closeModal();toast('Brochure on its way (demo)','mail')}});
 $('#unrsv')?.addEventListener('click',()=>{ls('reserved',(ls('reserved')||[]).filter(r=>!(r.dev===d.s&&r.u===sel.id)));drawUnits(d);toast('Reservation cancelled')})}
function reserve(d,u){const cur=CITY[d.city].cur;const m=modal(`<span class="lab">${d.n} · Residence ${u.id}</span><h3>Reserve this residence</h3><p class="muted">A fully refundable holding deposit of ${price(u.price*.05,cur)} secures ${u.id} for 14 days while contracts are prepared. Demo only, no payment is taken.</p>
 <form id="rs" novalidate style="display:grid;gap:10px"><div class="two"><input class="input" id="rn" placeholder="Full name" autocomplete="name" aria-label="Full name"><input class="input" id="re" type="email" placeholder="Email" autocomplete="email" aria-label="Email"></div><input class="input" id="rp" type="tel" placeholder="Phone with country code" autocomplete="tel" aria-label="Phone"><label style="display:flex;gap:10px;font-size:14px;color:var(--fg-2)"><input type="checkbox" id="rok" style="accent-color:var(--ember);width:17px;height:17px"> I have read the reservation terms.</label><p class="err-t" id="rerr" hidden></p><button class="btn em lg" type="submit">Confirm reservation</button></form>`);
 $('#rs',m).onsubmit=e=>{e.preventDefault();const v=id=>$('#'+id).value.trim();const bad=v('rn').length<2||!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test(v('re'))||v('rp').replace(/\D/g,'').length<8;if(bad||!$('#rok').checked){$('#rerr').hidden=false;$('#rerr').textContent=bad?'Please complete your name, email and phone.':'Please accept the reservation terms.';return}
  const nm=v('rn');const l=ls('reserved')||[];l.push({dev:d.s,u:u.id,n:nm,t:Date.now()});ls('reserved',l);closeModal();drawUnits(d);modal(`<span class="lab">Reservation ${d.s.toUpperCase()}-${u.id}</span><h3>${u.id} is held for you.</h3><p class="muted">Our new-homes team will call ${esc(nm.split(' ')[0])} within one business day to arrange contracts. You can view or cancel this under Saved.</p><a class="btn ink" href="#saved">Go to Saved</a>`)}}
function bindDev(d){drawUnits(d);$$('[data-ub]').forEach(b=>b.onclick=()=>{S.bedsF=+b.dataset.ub;S.unitSel=null;$$('[data-ub]').forEach(x=>x.setAttribute('aria-pressed',x===b));drawUnits(d)})}

/* ---------- SELL / valuation ---------- */
const PPM={syd:{'Elizabeth Bay':27000,'Bronte':24000,'Paddington':17000,'Surry Hills':15000,'Pyrmont':19000,'Mosman':16500},la:{'Hollywood Hills':12000,'Venice':15000,'Malibu':19000,'Silver Lake':10500,'Beverly Crest':11500,'Downtown':8500},lis:{'Chiado':9500,'Cascais':8800,'Restelo':8200,'Parque das Nações':7400,'Avenidas Novas':7000,'Comporta':9000}};
function pageSell(){const v=S.val||{city:'syd',m2:''};return `<section class="wrap ph-h"><div class="crumbs"><a href="#home">Home</a>/<span>Sell</span></div><h1 class="rv">What is your home <em>worth</em>?</h1><p class="rv">An instant estimate from recent sales in your neighbourhood. For an exact figure, book a free appraisal.</p></section>
 <section class="wrap"><div class="two" style="gap:24px;align-items:start"><form class="card" id="vf2" novalidate style="display:grid;gap:14px"><div class="two"><div class="field"><label for="vC">City</label><select class="sel" id="vC">${Object.entries(CITY).map(([k,c])=>`<option value="${k}" ${v.city===k?'selected':''}>${c.n}</option>`).join('')}</select></div><div class="field"><label for="vA">Neighbourhood</label><select class="sel" id="vA"></select></div></div>
  <div class="two"><div class="field"><label for="vT">Type</label><select class="sel" id="vT">${TYPES.map(t=>`<option>${t}</option>`).join('')}</select></div><div class="field"><label for="vM">Interior size (m²)</label><input class="input num" id="vM" inputmode="numeric" value="${v.m2||''}" placeholder="e.g. 180"></div></div>
  <div class="two"><div class="field"><span class="fl">Bedrooms</span><div class="seg full">${[1,2,3,4,5].map(b=>`<button type="button" data-vb="${b}" aria-pressed="${b===3}">${b}${b===5?'+':''}</button>`).join('')}</div></div><div class="field"><span class="fl">Condition</span><div class="seg full">${[['0.92','Needs work'],['1','Good'],['1.1','Renovated']].map((c,i)=>`<button type="button" data-vcn="${c[0]}" aria-pressed="${i===1}">${c[1]}</button>`).join('')}</div></div></div>
  <div class="field"><span class="fl">Views</span><div class="seg full">${[['1','None'],['1.06','Partial'],['1.15','Water']].map((c,i)=>`<button type="button" data-vv="${c[0]}" aria-pressed="${i===0}">${c[1]}</button>`).join('')}</div></div><p class="err-t" id="vErr" hidden>Enter a size between 30 and 2,000 m².</p><button class="btn ink lg" type="submit">Estimate my home</button></form><div id="vOut"><div class="est"><span class="lab" style="color:#B9B0A3">Your estimate</span><div class="rng" style="color:#6E6A63">—</div><p style="color:#B9B0A3">Fill in the form to see a range based on comparable homes.</p></div></div></div></section>`}
function bindSell(){let bd=3,cn=1,vw=1;const areas=()=>{$('#vA').innerHTML=Object.keys(CITY[$('#vC').value].areas).map(a=>`<option>${a}</option>`).join('')};areas();$('#vC').onchange=areas;
 const seg=(sel,set)=>$$(sel).forEach(b=>b.onclick=()=>{$$(sel).forEach(x=>x.setAttribute('aria-pressed',x===b));set(b)});seg('[data-vb]',b=>bd=+b.dataset.vb);seg('[data-vcn]',b=>cn=+b.dataset.vcn);seg('[data-vv]',b=>vw=+b.dataset.vv);
 const run=()=>{const m=+$('#vM').value;if(!(m>=30&&m<=2000)){$('#vErr').hidden=false;$('#vM').classList.add('err');return}$('#vErr').hidden=true;$('#vM').classList.remove('err');const c=$('#vC').value,a=$('#vA').value,t=$('#vT').value;const tf={House:1.05,Villa:1.15,Apartment:.95,Penthouse:1.2}[t];const mid=PPM[c][a]*m*tf*cn*vw*(1+(bd-3)*.02);const lo=mid*.92,hi=mid*1.08,cur=CITY[c].cur;
  const comps=L.filter(p=>p.city===c&&p.st!=='rent').sort((x,y)=>Math.abs(x.m2-m)-Math.abs(y.m2-m)).slice(0,3);
  $('#vOut').innerHTML=`<div class="est" style="animation:rise .5s var(--ease)"><span class="lab" style="color:#B9B0A3">Estimated value · ${esc(a)}</span><div class="rng num">${price(lo,cur,{compact:1})} – ${price(hi,cur,{compact:1})}</div><div class="bar"><i style="left:50%"></i></div><p style="color:#C9C1B5;font-size:14px">Mid-point ${price(mid,cur)} · about ${price(PPM[c][a]*tf*cn*vw,cur)} per m². Based on demo comparables; an agent appraisal will refine it.</p><button class="btn em" id="bkA">Book a free appraisal</button></div>
  <h3 style="font-size:24px;margin:24px 0 12px">Comparable homes</h3><div style="display:grid;gap:8px">${comps.map(p=>`<a class="rowi" href="#p-${p.id}" style="text-decoration:none">${ph(p.img[0],p.t)}<div class="g"><b>${esc(p.t)}</b><span class="muted" style="font-size:13px">${p.m2} m² · ${pLabel(p)} · ${price(p.price/p.m2,p.cur)}/m²</span></div></a>`).join('')}</div>`;
  $('#bkA').onclick=()=>{const a2=AG.filter(x=>x.city===c);const md=modal(`<h3>Book a free appraisal</h3><p class="muted">A local agent will visit, measure and give you a written appraisal within 48 hours.</p><form id="af" novalidate style="display:grid;gap:10px"><select class="sel" id="aa" aria-label="Agent">${a2.map(x=>`<option value="${x.id}">${x.n} · ${x.r}</option>`).join('')}</select><input class="input" id="an" placeholder="Full name" aria-label="Full name"><input class="input" id="ae" type="email" placeholder="Email" aria-label="Email"><input class="input" id="aad" placeholder="Property address" aria-label="Property address"><p class="err-t" id="aerr" hidden>Please complete all fields with a valid email.</p><button class="btn em lg" type="submit">Request appraisal</button></form>`);$('#af',md).onsubmit=e=>{e.preventDefault();if($('#an').value.trim().length<2||!/^[^\s@]+@[^\s@]+\.[^\s@]{2,}$/.test($('#ae').value.trim())||$('#aad').value.trim().length<6){$('#aerr').hidden=false;return}closeModal();toast(`${ag($('#aa').value)?.n||'Your agent'} will be in touch (demo)`,'phone')}}};
 $('#vf2').onsubmit=e=>{e.preventDefault();run()};if(S.val){run();S.val=null}}

/* ---------- AGENTS & SAVED ---------- */
function pageAgents(){return `<section class="wrap ph-h"><div class="crumbs"><a href="#home">Home</a>/<span>Agents</span></div><h1 class="rv">Our <em>agents</em></h1><p class="rv">Local specialists in Sydney, Los Angeles and Lisbon.</p><div class="chips" style="margin-top:22px">${[['all','All cities'],...Object.entries(CITY).map(([k,c])=>[k,c.n])].map((c,i)=>`<button class="chip" type="button" data-ac="${c[0]}" aria-pressed="${!i}">${c[1]}</button>`).join('')}</div></section><section class="wrap"><div class="ag" id="agG">${AG.map(agCard).join('')}</div></section>`}
function bindAgentsPage(){bindAgents();$$('[data-ac]').forEach(b=>b.onclick=()=>{$$('[data-ac]').forEach(x=>x.setAttribute('aria-pressed',x===b));$('#agG').innerHTML=AG.filter(a=>b.dataset.ac==='all'||a.city===b.dataset.ac).map(agCard).join('');bindAgents($('#agG'))})}
function pageSaved(){return `<section class="wrap ph-h"><div class="crumbs"><a href="#home">Home</a>/<span>Saved</span></div><h1 class="rv">Saved</h1><p class="rv">Favourites, searches, viewings and reservations are kept in this browser.</p><div class="chips" style="margin-top:22px">${[['fav','Favourites'],['srch','Searches'],['vw','Viewings'],['rsv','Reservations']].map((t,i)=>`<button class="chip" type="button" data-st="${t[0]}" aria-pressed="${(S.stab||'fav')===t[0]}">${t[1]}</button>`).join('')}</div></section><section class="wrap" id="svB"></section>`}
function drawSaved(){const t=S.stab||'fav',el=$('#svB');
 if(t==='fav'){const l=[...S.fav].map(lst).filter(Boolean);el.innerHTML=l.length?`<div class="lgrid">${l.map(card).join('')}</div>`:`<div class="empty"><h3 style="font-size:28px">No favourites yet</h3><p class="muted" style="margin:8px 0 16px">Tap the heart on any home to save it here.</p><a class="btn ink" href="#buy">Browse homes</a></div>`;bindCards(el)}
 if(t==='srch'){const l=ls('searches')||[];el.innerHTML=l.length?`<div style="display:grid;gap:8px">${l.map(s=>`<div class="rowi"><div class="g"><b>${esc(s.d)}</b><span class="muted" style="font-size:13px">${filtered(s.f).length} homes now · saved ${new Date(s.id).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><button class="btn ink sm" data-ss="${s.id}">Run search</button><button class="btn lt sm" data-sx="${s.id}">Delete</button></div>`).join('')}</div>`:`<div class="empty"><h3 style="font-size:28px">No saved searches</h3><p class="muted" style="margin:8px 0 16px">Use “Save search” on the listings page to get alerts.</p><a class="btn ink" href="#buy">Start a search</a></div>`;
  $$('[data-ss]',el).forEach(b=>b.onclick=()=>{const s=l.find(x=>x.id==b.dataset.ss);S.f={...s.f};S.keepF=1;location.hash=s.f.mode==='rent'?'rent':s.f.mode==='new'?'new':'buy'});$$('[data-sx]',el).forEach(b=>b.onclick=()=>{ls('searches',l.filter(x=>x.id!=b.dataset.sx));drawSaved()})}
 if(t==='vw'){const l=(ls('viewings')||[]).sort((a,b)=>(a.d+a.t).localeCompare(b.d+b.t));el.innerHTML=l.length?`<div style="display:grid;gap:8px">${l.map(v=>{const p=lst(v.pid);return `<div class="rowi">${ph(p.img[0])}<div class="g"><b>${esc(p.t)}</b><span class="muted" style="font-size:13px">${fmtD(v.d,{weekday:'long',month:'short',day:'numeric'})} · ${v.t} · ${v.mode==='video'?'Live video':'In person'} · ${v.id}</span></div><a class="btn lt sm" href="#p-${p.id}">View home</a><button class="btn lt sm" data-vx="${v.id}" style="color:var(--bad)">Cancel</button></div>`}).join('')}</div>`:`<div class="empty"><h3 style="font-size:28px">No viewings booked</h3><p class="muted" style="margin:8px 0 16px">Book from any listing page.</p><a class="btn ink" href="#buy">Find a home</a></div>`;
  $$('[data-vx]',el).forEach(b=>b.onclick=()=>{ls('viewings',(ls('viewings')||[]).filter(x=>x.id!==b.dataset.vx));drawSaved();toast('Viewing cancelled')})}
 if(t==='rsv'){const l=ls('reserved')||[];el.innerHTML=l.length?`<div style="display:grid;gap:8px">${l.map(r=>{const d=dev(r.dev);const u=units(d).find(x=>x.id===r.u);return `<div class="rowi">${ph(d.img[0])}<div class="g"><b>${d.n} · ${r.u}</b><span class="muted" style="font-size:13px">${u.bd} bed · ${u.m2} m² · ${price(u.price,CITY[d.city].cur)} · held 14 days from ${new Date(r.t).toLocaleDateString('en-US',{month:'short',day:'numeric'})}</span></div><a class="btn lt sm" href="#dev-${d.s}">View</a><button class="btn lt sm" data-rx="${r.dev}|${r.u}" style="color:var(--bad)">Cancel</button></div>`}).join('')}</div>`:`<div class="empty"><h3 style="font-size:28px">No reservations</h3><p class="muted" style="margin:8px 0 16px">Reserve a residence in one of our developments.</p><a class="btn ink" href="#new">New developments</a></div>`;
  $$('[data-rx]',el).forEach(b=>b.onclick=()=>{const [dv,u]=b.dataset.rx.split('|');ls('reserved',(ls('reserved')||[]).filter(r=>!(r.dev===dv&&r.u===u)));drawSaved();toast('Reservation cancelled')})}}
function bindSaved(){$$('[data-st]').forEach(b=>b.onclick=()=>{S.stab=b.dataset.st;$$('[data-st]').forEach(x=>x.setAttribute('aria-pressed',x===b));drawSaved()});drawSaved()}

/* ---------- motion ---------- */
let io;
function initReveal(){io?.disconnect();io=new IntersectionObserver(es=>es.forEach(e=>{if(!e.isIntersecting)return;const t=e.target;t.classList.add('in');io.unobserve(t);$$('[data-count]',t).forEach(countUp);$$('.lines',t).forEach(x=>x.classList.add('in'))}),{threshold:.12,rootMargin:'0px 0px -6% 0px'});$$('.rv,.lines').forEach(el=>RM?(el.classList.add('in'),$$('[data-count]',el).forEach(x=>countUp(x,1))):io.observe(el))}
function countUp(el,now){if(el.dataset.done)return;el.dataset.done=1;const to=+el.dataset.count,dec=+el.dataset.dec||0,pre=el.dataset.pre||'';const f=v=>pre+(dec?v.toFixed(dec):Math.round(v));if(now||RM){el.textContent=f(to);return}const t0=performance.now();const s=t=>{const p=Math.min(1,(t-t0)/1500);el.textContent=f(to*(1-Math.pow(1-p,4)));if(p<1)requestAnimationFrame(s)};requestAnimationFrame(s)}
let tick=false;
function frame(){tick=false;const y=scrollY,vh=innerHeight;const nav=$('#nav');nav?.classList.toggle('small',y>60);if(RM)return;
 const hi=$('#heroImg');if(hi&&innerWidth>980){const p=clamp(y/(vh*.7),0,1);hi.style.transform=`scale(${1-p*.08})`;hi.style.borderRadius=`${p*40}px`;hi.style.inset=`${p*14}px`;$$('.fcard').forEach(c=>c.style.translate=`0 ${(-y*(+c.dataset.par||0)).toFixed(1)}px`);const w=$('.wordmark');if(w)w.style.transform=`translateY(${-p*40}px)`}
 $$('.jr-card[data-par]').forEach(c=>{const r=c.parentElement.getBoundingClientRect();c.style.translate=`0 ${((r.top+r.height/2-vh/2)*+c.dataset.par).toFixed(1)}px`});
 const pj=$('#pj');if(pj&&innerWidth>900){const r=pj.getBoundingClientRect(),p=clamp(-r.top/(pj.offsetHeight-vh),0,1);const i=Math.min(DEV.length-1,Math.floor(p*DEV.length*.999));$('#pjBar').style.transform=`scaleX(${p})`;$('#pjBar').style.width='100%';
  if(S.pjI!==i){S.pjI=i;$$('[data-pjt]').forEach(t=>{const k=+t.dataset.pjt;t.className='t '+(k===i?'':k<i?'out':'nx')});$$('[data-pji]').forEach(t=>t.classList.toggle('out',+t.dataset.pji!==i));$$('[data-pjd]').forEach(t=>t.innerHTML=+t.dataset.pjd===i?`<b>(${i+1})</b>`:`(${+t.dataset.pjd+1})`);$('#pjD').textContent=DEV[i].d;$('#pjA').textContent='Explore '+DEV[i].n;$('#pjA').href='#dev-'+DEV[i].s}
  $$('[data-pji]').forEach(t=>{if(+t.dataset.pji===i){const j=[...t.classList].find(c=>/^i\d$/.test(c));const lp=(p*DEV.length)%1;t.style.transform=`translateY(${(lp-.5)*(j==='i2'?-40:j==='i1'?60:30)}px)`}})}}
addEventListener('scroll',()=>{if(!tick){tick=true;requestAnimationFrame(frame)}},{passive:true});
