function sizePj(){const pj=$('#pj');if(pj)pj.style.height=innerWidth>900?`${(DEV.length+.6)*100}vh`:''}

/* ---------- router ---------- */
function route(){const h=(location.hash||'#home').slice(1)||'home';closeModal();$('#mm')?.classList.remove('open');if(['explore','featured'].includes(h)){if(S.page!=='home')render('home');document.getElementById(h)?.scrollIntoView({behavior:'smooth'});return}render(h);scrollTo(0,0)}
function render(h,keep){S.timers.forEach(clearInterval);S.timers=[];S.pjI=null;if(!keep)S.vw=null;
 let body,bind,cur=h;
 if(['buy','rent','new'].includes(h)){if(keep)S.keepF=1;body=pageList(h);bind=bindList}
 else if(h.startsWith('p-')&&lst(h.slice(2))){const p=lst(h.slice(2));body=pageProp(p);bind=()=>bindProp(p);cur=p.st==='rent'?'rent':p.st==='offplan'?'new':'buy'}
 else if(h.startsWith('dev-')&&dev(h.slice(4))){const d=dev(h.slice(4));if(!keep){S.unitSel=null;S.bedsF=0}body=pageDev(d);bind=()=>bindDev(d);cur='new'}
 else if(h==='sell'){body=pageSell();bind=bindSell}
 else if(h==='agents'){body=pageAgents();bind=bindAgentsPage}
 else if(h==='saved'){body=pageSaved();bind=bindSaved}
 else{h='home';cur='home';body=pageHome();bind=bindHome}
 S.page=h;document.title=({buy:'Homes for sale',rent:'Homes to rent',new:'New developments',sell:'Valuation',agents:'Agents',saved:'Saved'}[h]||(h.startsWith('p-')?lst(h.slice(2)).t:h.startsWith('dev-')?dev(h.slice(4)).n:''))+(h==='home'?'Aurelle Estates · Homes, Residences & Developments':' · Aurelle Estates');
 mount(cur,body);bind&&bind();bindAgents($('#main'));drawTray();sizePj();initReveal();frame()}
addEventListener('hashchange',route);
document.addEventListener('click',e=>{const a=e.target.closest('a[href^="#"]');if(!a)return;if(location.hash===a.getAttribute('href')){e.preventDefault();route()}});
route();
